-- Blacklisted plate: impossible travel CAM-01 -> CAM-08 (5s apart)
INSERT INTO sightings (source_event_id, camera_id, plate_id, raw_plate_text, normalized_plate_candidate, detection_confidence, ocr_confidence, ocr_candidates, validation_status, spotted_at, direction_degrees, vehicle_type, vehicle_color, lane_number, model_version)
VALUES
  ('seed-DL8CAF5678-CAM-01', (SELECT camera_id FROM cameras WHERE camera_code='CAM-01'), (SELECT plate_id FROM plates WHERE normalized_plate='DL8CAF5678'), 'DL8CAF5678', 'DL8CAF5678', 0.93, 0.88, '[]'::jsonb, 'accepted', now() - make_interval(secs => 600), 180, 'car', 'black', 3, 'anpr-v1'),
  ('seed-DL8CAF5678-CAM-08', (SELECT camera_id FROM cameras WHERE camera_code='CAM-08'), (SELECT plate_id FROM plates WHERE normalized_plate='DL8CAF5678'), 'DL8CAF5678', 'DL8CAF5678', 0.93, 0.88, '[]'::jsonb, 'accepted', now() - make_interval(secs => 595), 180, 'car', 'black', 3, 'anpr-v1');

-- Blacklist entry
INSERT INTO blacklist_entries (plate_id, reason, severity, status, added_by, case_reference)
SELECT plate_id, 'Reported stolen (demo)', 'high', 'active', 'seed', 'DWK-CASE-001' FROM plates WHERE normalized_plate='DL8CAF5678';

-- Demo alerts
INSERT INTO alerts (dedup_key, alert_type, sighting_id, blacklist_entry_id, status, match_confidence, details)
SELECT 'seed-bl-DL8CAF5678-CAM01', 'blacklist', s.sighting_id, b.blacklist_entry_id, 'new', 1.0,
       jsonb_build_object('note','blacklisted vehicle seen','camera','CAM-01')
FROM sightings s JOIN plates p ON p.plate_id=s.plate_id AND p.normalized_plate='DL8CAF5678'
JOIN blacklist_entries b ON b.plate_id=p.plate_id
WHERE s.source_event_id='seed-DL8CAF5678-CAM-01';

INSERT INTO alerts (dedup_key, alert_type, sighting_id, previous_sighting_id, anomaly_reason, status, match_confidence, details)
SELECT 'seed-anom-DL8CAF5678', 'route_anomaly', cur.sighting_id, prev.sighting_id, 'impossible_travel_time', 'new', 0.98, jsonb_build_object('observed_seconds',5,'note','CAM-01 to CAM-08 in 5s')
FROM sightings cur JOIN sightings prev ON prev.source_event_id='seed-DL8CAF5678-CAM-01'
WHERE cur.source_event_id='seed-DL8CAF5678-CAM-08';

COMMIT;
